// ================= limites de Pernambuco (estado e municípios) =================
map.createPane('limites'); map.getPane('limites').style.zIndex = 350; map.getPane('limites').style.pointerEvents = 'none';
const LIM = {est: L.layerGroup(), mun: L.layerGroup(), rot: L.layerGroup(), bb: new Map(), pronto: false};
const ringLL = f => { const r = []; for (let k = 0; k < f.length; k += 2) r.push([f[k + 1], f[k]]); return r; };
function limCentro(ll) { // centroide simples da maior parte
  let a = 0, cx = 0, cy = 0;
  for (let k = 0; k < ll.length; k++) { const p = ll[k], q = ll[(k + 1) % ll.length], c = p[1] * q[0] - q[1] * p[0]; a += c; cx += (p[1] + q[1]) * c; cy += (p[0] + q[0]) * c; }
  return Math.abs(a) < 1e-12 ? ll[0] : [cy / (3 * a), cx / (3 * a)];
}
function limConstruir() {
  if (LIM.pronto) return; LIM.pronto = true;
  for (const f of PE.e) L.polyline(ringLL(f), {pane: 'limites', interactive: false, className: 'lim-est'}).addTo(LIM.est);
  for (const m of PE.m) {
    let maior = null, ba = -1, bb = null;
    for (const f of m.p) {
      const ll = ringLL(f); L.polyline(ll, {pane: 'limites', interactive: false, className: 'lim-mun'}).addTo(LIM.mun);
      const b = L.latLngBounds(ll); bb = bb ? bb.extend(b) : b;
      const ar = (b.getEast() - b.getWest()) * (b.getNorth() - b.getSouth()); if (ar > ba) { ba = ar; maior = ll; }
    }
    LIM.bb.set(m.c, {nome: m.n, bb, c: limCentro(maior)});
  }
  limEstilo();
}
function limEstilo() {
  const c = CFG.limites;
  LIM.est.eachLayer(l => l.setStyle({color: c.estCor, weight: c.estW, opacity: 1, fill: false}));
  LIM.mun.eachLayer(l => l.setStyle({color: c.munCor, weight: c.munW, opacity: .9, fill: false, dashArray: c.munTrac ? '5 4' : null}));
  limRotulos();
}
function limRotulos() {
  LIM.rot.clearLayers();
  if (!CFG.limites.mun || !CFG.limites.rot || map.getZoom() < 9) return;
  const vb = map.getBounds().pad(.1);
  for (const [, v] of LIM.bb) {
    if (!vb.contains(v.c)) continue;
    L.marker(v.c, {pane: 'limites', interactive: false, icon: L.divIcon({className: 'lim-rot', html: `<span style="color:${CFG.limites.rotCor}">${esc(v.nome)}</span>`, iconSize: [0, 0]})}).addTo(LIM.rot);
  }
}
function limAplicar() {
  limConstruir();
  const c = CFG.limites;
  c.est ? LIM.est.addTo(map) : LIM.est.remove();
  c.mun ? (LIM.mun.addTo(map), LIM.rot.addTo(map)) : (LIM.mun.remove(), LIM.rot.remove());
  limRotulos();
  const a = $('#lim-est'), b = $('#lim-mun'); if (a) a.checked = !!c.est; if (b) b.checked = !!c.mun;
}
function limMunicipios(q) {
  const n = norm(q); if (n.length < 2) return [];
  limConstruir();
  return [...LIM.bb.entries()].filter(([, v]) => norm(v.nome).startsWith(n) || norm(v.nome).includes(' ' + n)).slice(0, 5).map(([c, v]) => ({t: 'Município ' + v.nome + ' (PE)', mun: c, ic: '🗺️'}));
}
const norm = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
function irMunicipio(c) { const v = LIM.bb.get(c); if (!v) return; map.fitBounds(v.bb.pad(.05)); if (!CFG.limites.mun) { CFG.limites.mun = true; salvar(); limAplicar(); } }
function limLigar() {
  $('#lim-est').onchange = e => { CFG.limites.est = e.target.checked; salvar(); limAplicar(); };
  $('#lim-mun').onchange = e => { CFG.limites.mun = e.target.checked; salvar(); limAplicar(); };
  map.on('moveend zoomend', limRotulos);
}
